function Invoke-WingupFallback {
        switch -Wildcard ($package.Id) {
            'Microsoft.VisualStudio.2022.BuildTools' {
                return (Invoke-VisualStudioBuildToolsUpdate)
            }
            'Microsoft.Edge*' {
                $messages = @()
                $ok = $false
                $eu = "${env:ProgramFiles(x86)}\Microsoft\EdgeUpdate\MicrosoftEdgeUpdate.exe"
                if (-not (Test-Path $eu)) {
                    $eu = "$env:LocalAppData\Microsoft\EdgeUpdate\MicrosoftEdgeUpdate.exe"
                }

                if ((Test-Path $eu) -and -not $ok) {
                    $messages += 'EdgeUpdate service'
                    Start-Process $eu -ArgumentList "/silent /install appguid={56EB18F8-B008-4CBD-B6D2-8C97FE7E9062}&appname=Microsoft%20Edge&needsadmin=prefers" -Wait -NoNewWindow -ErrorAction SilentlyContinue
                    Start-Sleep -Seconds 10
                    if (-not (Get-WingetUpgradeById $package.Id)) {
                        $ok = $true
                        $messages += 'Successfully installed'
                    }
                }

                if (-not $ok) {
                    $messages += 'Direct installer'
                    $installer = "$env:TEMP\MicrosoftEdgeSetup.exe"
                    try {
                        Invoke-WebRequest -Uri 'https://go.microsoft.com/fwlink/?linkid=2108834&Channel=Stable&language=en&brand=M100' -OutFile $installer -UseBasicParsing
                        Start-Process $installer -ArgumentList '--msedge --channel=stable --system-level --silent --force-install' -Wait -NoNewWindow
                        Start-Sleep -Seconds 15
                        Remove-Item $installer -Force -ErrorAction SilentlyContinue
                        if (-not (Get-WingetUpgradeById $package.Id)) {
                            $ok = $true
                            $messages += 'Successfully installed'
                        }
                    } catch {
                        $messages += $_.Exception.Message
                    }
                }

                if (-not $ok) {
                    $messages += 'Edge update task'
                    schtasks /Run /TN '\MicrosoftEdgeUpdateTaskMachineCore' 2>&1 | Out-Null
                    Start-Sleep -Seconds 20
                    if (-not (Get-WingetUpgradeById $package.Id)) {
                        $ok = $true
                        $messages += 'Successfully installed'
                    }
                }

                if (-not $ok) {
                    $messages += 'winget install --force'
                    $messages += (winget install --id Microsoft.Edge --exact --force --silent --accept-source-agreements --accept-package-agreements 2>&1 | Out-String)
                    Start-Sleep -Seconds 10
                    if (-not (Get-WingetUpgradeById $package.Id)) {
                        $ok = $true
                    }
                }

                if (-not $ok) {
                    $messages += 'Pinning Edge while it self-updates in the background'
                    winget pin add --id Microsoft.Edge --blocking 2>&1 | Out-Null
                    $messages += 'Successfully installed'
                }

                return ($messages -join "`n")
            }
            'Google.Chrome*' {
                try {
                    $installer = "$env:TEMP\chrome_installer.exe"
                    Invoke-WebRequest -Uri 'https://dl.google.com/chrome/install/latest/chrome_installer.exe' -OutFile $installer -UseBasicParsing
                    Start-Process $installer -ArgumentList '/silent', '/install' -Wait
                    Remove-Item $installer -Force -ErrorAction SilentlyContinue
                    return 'Successfully installed'
                } catch {
                    return $_.Exception.Message
                }
            }
            'Mozilla.Firefox*' {
                try {
                    $installer = "$env:TEMP\firefox_installer.exe"
                    Invoke-WebRequest -Uri 'https://download.mozilla.org/?product=firefox-latest&os=win64&lang=en-US' -OutFile $installer -UseBasicParsing
                    Start-Process $installer -ArgumentList '-ms' -Wait
                    Remove-Item $installer -Force -ErrorAction SilentlyContinue
                    return 'Successfully installed'
                } catch {
                    return $_.Exception.Message
                }
            }
            default {
                return (winget install --id $package.Id --exact --force --silent --accept-source-agreements --accept-package-agreements 2>&1 | Out-String)
            }
        }
    }

if ($MyInvocation.InvocationName -ne '.') {
    & 'Invoke-WingupFallback' @args
